package com.rotarypumpers.meraki;
import android.content.Context;import android.graphics.*;import android.view.View;import org.json.*;import java.util.*;import com.rotarypumpers.meraki.core.*;
final class CupFlowChart extends View {
 private final JSONObject shot,reference;private final Paint p=new Paint(3);
 CupFlowChart(Context c,JSONObject s,JSONObject r){super(c);shot=s;reference=r;p.setTypeface(c.getResources().getFont(R.font.space_grotesk));setContentDescription("Calculated cup flow over brew time. Copper is this shot; dashed tan is favourite reference. Gaps are not connected.");}
 protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density,l=36*d,r=getWidth()-12*d,t=26*d,b=getHeight()-36*d;double duration=shot.optDouble("duration_estimate_s",0),max=2;List<double[]> rows=ShotInsights.curve(shot),other=reference==null?Collections.emptyList():ShotInsights.curve(reference);if(reference!=null)duration=Math.max(duration,reference.optDouble("duration_estimate_s",0));if(duration<=0)return;
  for(List<double[]> list:Arrays.asList(rows,other))for(double[] v:list)if(Double.isFinite(v[1]))max=Math.max(max,Math.ceil(v[1]));p.setTextSize(11*d);p.setStyle(Paint.Style.FILL);p.setColor(0xffefb48d);c.drawText("Cup flow · g/s",l,15*d,p);
  for(int i=0;i<3;i++){float y=b-(b-t)*i/2;p.setColor(0xff505954);c.drawLine(l,y,r,y,p);p.setColor(0xffc2c7c2);c.drawText(String.format(Locale.US,"%.1f",max*i/2),0,y,p);String label=String.format(Locale.US,"%.0fs",duration*i/2);float x=l+(r-l)*i/2;c.drawText(label,i==2?x-p.measureText(label):x,b+22*d,p);}
  int save=c.save();c.clipRect(l,t,r,b);for(int k=0;k<2;k++){List<double[]> list=k==0?other:rows;Path path=new Path();boolean begun=false;for(double[] v:list){if(!Double.isFinite(v[1])){begun=false;continue;}float x=(float)(l+(r-l)*v[0]/duration),y=(float)(b-(b-t)*v[1]/max);if(begun)path.lineTo(x,y);else path.moveTo(x,y);begun=true;}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2*d);p.setColor(k==0?0xffc2c7c2:0xffefb48d);p.setPathEffect(k==0?new DashPathEffect(new float[]{5*d,4*d},0):null);c.drawPath(path,p);}p.setPathEffect(null);
  JSONArray gaps=shot.optJSONArray("sampling_gaps");if(gaps!=null){p.setColor(0x55e8bb7c);p.setStyle(Paint.Style.FILL);double start=ShotInsights.bound(shot,"start_bounds");for(int i=0;i<gaps.length();i++){JSONObject g=gaps.optJSONObject(i);float x1=(float)(l+(r-l)*(g.optDouble("before_uptime")-start)/duration),x2=(float)(l+(r-l)*(g.optDouble("after_uptime")-start)/duration);c.drawRect(x1,t,x2,b,p);}}c.restoreToCount(save);p.setStyle(Paint.Style.FILL);
 }
}
